command:
tmp=$(mktemp -d); export PMW_HOME="$tmp" PMW_PROJECT_SLUG=p0-snapshot; root="$PMW_HOME/projects/$PMW_PROJECT_SLUG"; mkdir -p "$root/runs"; printf '{"slug":"p0-snapshot","current_run_id":"new","latest_run_id":"new","latest_run_status":"已开始","current_task_digest":"newdigest","current_input_revision":"newrev","last_controller_verdict":"new"}
' > "$root/project.json"; printf '{"event":"task_intake","run_id":"old","task_digest":"olddigest","input_revision":"oldrev","controller_verdict":"old","status":"old"}
' > "$root/runs/old.jsonl"; printf '{"event":"task_intake","run_id":"new","task_digest":"newdigest","input_revision":"newrev","controller_verdict":"new","status":"new"}
' > "$root/runs/new.jsonl"; bin/pmw-run event --run old --type gate --status 已确认 --title 测试 --summary 测试 >/dev/null; bin/pmw-artifact add --run old --kind browser_evidence --title old --status 已采集 --source-skill test --summary old >/dev/null; tail -n 1 "$root/runs/old.jsonl"; tail -n 1 "$root/artifact-flow.jsonl"
